using System;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEngine;using SkyIsland;
public static class HarborReview {
 public static void Validate(){int n=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("HARBOR FAIL "+name);n++;};
  Func<Vector3,float?> floor=p=>1;var walk=new ExplorerMotor(Vector3.up);var run=new ExplorerMotor(Vector3.up);for(int i=0;i<20;i++){walk.Step(Vector3.right,false,.05f,floor);run.Step(Vector3.right,false,.05f,floor,null,null,true);}check(Mathf.Abs(walk.Position.x-3.2f)<.001f&&Mathf.Abs(run.Position.x-5.6f)<.001f,"walk and shift sprint speeds");
  run=new ExplorerMotor(Vector3.up);run.Step(new Vector3(1,0,1),false,.05f,floor,null,null,true);check(Mathf.Abs(new Vector2(run.Position.x,run.Position.z).magnitude-.28f)<.001f,"diagonal sprint not faster");run=new ExplorerMotor(Vector3.up);run.Step(Vector3.right,false,.05f,floor,p=>p.x>.1f,null,true);check(run.Position.x==0,"sprint retains collision");run.Step(Vector3.zero,true,.05f,floor,null,null,true);check(!run.Grounded,"sprint preserves jump");float before=run.Position.x;run.Step(Vector3.right,false,.05f,floor,null,null,true);check(Mathf.Abs(run.Position.x-before-.16f)<.001f,"no airborne sprint boost");
  var island=new HexIsland{Wood=50,Stone=50};var h=new HarborState{initialized=true};check(!DockRules.Edge(new DockState{cell=new Hex(0,0),edge=0},island),"interior edge rejected");check(!DockRules.Edge(new DockState{cell=new Hex(8,0),edge=0},island),"unowned tile rejected");check(!DockRules.Edge(new DockState{cell=new Hex(1,0),edge=6},island),"invalid rotation rejected");var dock=new DockState{cell=new Hex(1,0),edge=0};check(DockRules.Add(h.docks,dock,island),"exposed edge accepted");check(DockRules.Place(h,dock,island,()=>false)=="save-failed"&&h.docks.Count==0&&island.Wood==50&&island.Stone==50,"failed dock save rolls back cost");check(DockRules.Place(h,dock,island,()=>true)=="complete"&&h.docks.Count==1&&island.Wood==38&&island.Stone==46,"place cost once");check(!DockRules.Add(h.docks,dock,island),"duplicate dock rejected");check(DockRules.Blocks(h.docks,new Hex(1,0))&&DockRules.Blocks(h.docks,new Hex(2,0)),"anchor and outward foundation protected");check(DockRules.Floor(h.docks,dock.Center+Vector3.up)==dock.Center.y+.65f,"net is walkable floor");check(!DockRules.Floor(h.docks,dock.Center-Vector3.up).HasValue,"net not teleport floor from below");check(!DockRules.Contains(dock,dock.Center+Vector3.right*5),"outside net rejected");h.hasParked=true;h.parked=dock.Center+Vector3.up*.25f;check(DockRules.Valid(JsonUtility.FromJson<HarborState>(JsonUtility.ToJson(h)),island),"dock and parked hull persist");island.Cells.Add(new Hex(2,0));check(!DockRules.Valid(h,island),"covered edge invalid");island.Cells.Remove(new Hex(2,0));h.parked=new Vector3(float.NaN,0,0);check(!DockRules.Valid(h,island),"invalid parked position rejected");island.Wood=0;check(DockRules.Place(new HarborState(),dock,island,()=>true)=="materials","insufficient material no placement");
  Directory.CreateDirectory("../evidence/unity");File.WriteAllText("../evidence/unity/harbor-tests.txt","PASS "+n+" sprint/edge/placement/save/net-floor assertions; UTC "+DateTime.UtcNow.ToString("o")+"\nUnity rules executed. Browser controls and phone performance pending.");Debug.Log("SKY_HARBOR_TESTS_PASS "+n);
 }
 public static void Scene(SkyIslandPrototype prototype){
  var flags=BindingFlags.Instance|BindingFlags.NonPublic;var type=typeof(SkyIslandPrototype);var h=(SurvivalState)type.GetField("survival",flags).GetValue(prototype);var ship=(Transform)type.GetField("airship",flags).GetValue(prototype);if(h.harbor.docks.Count!=1)throw new Exception("Expected one starter dock");var d=h.harbor.docks[0];if(!d.cell.Equals(new Hex(0,1)))throw new Exception("Starter dock should be near spawn");if(!DockRules.Contains(d,ship.position)||Mathf.Abs(ship.position.y-(d.Center.y+.25f))>.001f)throw new Exception("Ship not berthed on starter net");var markers=UnityEngine.Object.FindObjectsOfType<DockMarker>();if(markers.Length!=1||markers[0].GetComponent<BoxCollider>()==null)throw new Exception("Dock scene collider missing");var args=new object[]{ship.position,Vector3.zero,Vector3.zero};bool can=(bool)type.GetMethod("LandingAt",flags).Invoke(prototype,args);if(!can||Vector3.Distance((Vector3)args[1],ship.position)>.001f)throw new Exception("Runtime landing lookup failed");args[0]=new Vector3(100,3,100);if((bool)type.GetMethod("LandingAt",flags).Invoke(prototype,args))throw new Exception("Void landing should fail");
  args[0]=new Hex(0,1).World+Vector3.up*3;if(!(bool)type.GetMethod("LandingAt",flags).Invoke(prototype,args))throw new Exception("Island ground landing should work");args[0]=Vector3.up*3;if((bool)type.GetMethod("LandingAt",flags).Invoke(prototype,args))throw new Exception("Fountain landing should fail");
  File.WriteAllText("../evidence/unity/harbor-scene-tests.txt","PASS 8 starter-net-near-spawn/hull-berth/BoxCollider/runtime-landing/void/island/fountain assertions; editor-assembled live Unity objects; UTC "+DateTime.UtcNow.ToString("o")+"\nNot actual keyboard or mobile verification.");Debug.Log("SKY_HARBOR_SCENE_PASS 8");
 }
}
